this.data.h.region_reqs_panv3="\u041d\u0415\u0422 \u0414\u0410\u041d\u041d\u042b\u0425";this.data.h.region_reqs_panv1="\u041e\u0427\u041a\u0418 \u0417\u0410\u0425\u0412\u0410\u0422\u0410: ";this.data.h.ruins_conq_label9="1. \u0412 \u0437\u0430\u0445\u0432\u0430\u0442\u0430\u0445 \u043c\u043e\u0433\u0443\u0442 \u0443\u0447\u0430\u0441\u0442\u0432\u043e\u0432\u0430\u0442\u044c \u0432\u0441\u0435 \u0438\u0433\u0440\u043e\u043a\u0438, \u0441\u043e\u0441\u0442\u043e\u044f\u0449\u0438\u0435 \u0432 \u0433\u0438\u043b\u044c\u0434\u0438\u044f\u0445.\n\n2. \u0420\u0430\u0439\u043e\u043d \u043f\u0435\u0440\u0435\u0445\u043e\u0434\u0438\u0442 \u0432\u043e \u0432\u043b\u0430\u0434\u0435\u043d\u0438\u0435 \u0433\u0438\u043b\u044c\u0434\u0438\u0438, \u043f\u0435\u0440\u0432\u043e\u0439 \u043d\u0430\u0431\u0440\u0430\u0432\u0448\u0435\u0439 \u043d\u0435\u043e\u0431\u0445\u043e\u0434\u0438\u043c\u043e\u0435 \u043a\u043e\u043b\u0438\u0447\u0435\u0441\u0442\u0432\u043e \u043e\u0447\u043a\u043e\u0432 \u0437\u0430\u0445\u0432\u0430\u0442\u0430.\n\u0412 \u0441\u043b\u0443\u0447\u0430\u0435, \u0435\u0441\u043b\u0438 \u043d\u0438 \u043e\u0434\u043d\u0430 \u0433\u0438\u043b\u044c\u0434\u0438\u044f \u043d\u0435 \u043d\u0430\u0431\u0440\u0430\u043b\u0430 \u043d\u0435\u043e\u0431\u0445\u043e\u0434\u0438\u043c\u043e\u0435 \u0447\u0438\u0441\u043b\u043e \u043e\u0447\u043a\u043e\u0432 \u0437\u0430 \u043e\u0442\u0432\u0435\u0434\u0435\u043d\u043d\u043e\u0435 \u0432\u0440\u0435\u043c\u044f, \u0440\u0430\u0439\u043e\u043d \u043e\u0441\u0442\u0430\u0435\u0442\u0441\u044f \u043d\u0435\u0437\u0430\u0445\u0432\u0430\u0447\u0435\u043d\u043d\u044b\u043c.\n\n3. \u041e\u0447\u043a\u0438 \u0437\u0430\u0445\u0432\u0430\u0442\u0430 \u043d\u0430\u0447\u0438\u0441\u043b\u044f\u044e\u0442\u0441\u044f \u0437\u0430 \u043f\u043e\u0431\u0435\u0434\u0443 \u0447\u043b\u0435\u043d\u0430\u043c\u0438 \u0433\u0438\u043b\u044c\u0434\u0438\u0438 \u0431\u043e\u0441\u0441\u043e\u0432, \u043d\u0430\u0445\u043e\u0434\u044f\u0449\u0438\u0445\u0441\u044f \u0432 \u0437\u0430\u0445\u0432\u0430\u0442\u044b\u0432\u0430\u0435\u043c\u043e\u043c \u0440\u0430\u0439\u043e\u043d\u0435. \u0417\u0430 \u043f\u043e\u0431\u0435\u0434\u0443 \u043d\u0430\u0434 \u043a\u0430\u0436\u0434\u044b\u043c \u0431\u043e\u0441\u0441\u043e\u043c \u043d\u0430\u0447\u0438\u0441\u043b\u044f\u0435\u0442\u0441\u044f 1 \u043e\u0447\u043a\u043e \u0437\u0430\u0445\u0432\u0430\u0442\u0430.\n\n4. \u041a\u043e\u0433\u0434\u0430 \u0433\u0438\u043b\u044c\u0434\u0438\u044f \u0437\u0430\u0445\u0432\u0430\u0442\u0438\u0442 \u0440\u0430\u0439\u043e\u043d, \u0442\u043e \u043d\u0430\u0447\u0438\u043d\u0430\u044f \u0441\u043e \u0441\u043b\u0435\u0434\u0443\u044e\u0449\u0435\u0433\u043e \u0434\u043d\u044f \u043f\u043e\u0441\u043b\u0435 \u0437\u0430\u0445\u0432\u0430\u0442\u0430 \u0438 \u0434\u043e \u043d\u0430\u0447\u0430\u043b\u0430 \u043d\u043e\u0432\u043e\u0433\u043e \u0437\u0430\u0445\u0432\u0430\u0442\u0430 \u0432\u0441\u0435 \u0447\u043b\u0435\u043d\u044b \u0433\u0438\u043b\u044c\u0434\u0438\u0438 \u0431\u0443\u0434\u0443\u0442 \u0435\u0436\u0435\u0434\u043d\u0435\u0432\u043d\u043e \u043f\u043e\u043b\u0443\u0447\u0430\u0442\u044c \u0434\u0430\u043d\u044c \u0441 \u0437\u0430\u0445\u0432\u0430\u0447\u0435\u043d\u043d\u043e\u0433\u043e \u0440\u0430\u0439\u043e\u043d\u0430.\n\n5. \u0420\u0430\u0437\u043c\u0435\u0440 \u0434\u0430\u043d\u0438 \u0437\u0430\u0432\u0438\u0441\u0438\u0442 \u043e\u0442 \u0441\u0443\u043c\u043c\u0430\u0440\u043d\u043e\u0433\u043e \u0447\u0438\u0441\u043b\u0430 \u0431\u043e\u0441\u0441\u043e\u0432, \u043f\u043e\u0431\u0435\u0436\u0434\u0435\u043d\u043d\u044b\u0445 \u0432\u0441\u0435\u043c\u0438 \u0438\u0433\u0440\u043e\u043a\u0430\u043c\u0438 \u0432 \u0437\u0430\u0445\u0432\u0430\u0447\u0435\u043d\u043d\u043e\u043c \u0440\u0430\u0439\u043e\u043d\u0435.";
