this.data.h.cortana_say_3="\u0418\u0434\u0435\u043c, \u043e\u0442\u0434\u0430\u043c \u0442\u0435\u0431\u0435 \u0442\u0432\u043e\u0435 \u043e\u0440\u0443\u0436\u0438\u0435. \n\u041c\u044b \u043f\u043e\u0434\u043e\u0431\u0440\u0430\u043b\u0438 \u0435\u0433\u043e \u0440\u044f\u0434\u043e\u043c \u0441 \u0442\u043e\u0431\u043e\u0439 \u043d\u0430 \u0434\u043e\u0440\u043e\u0433\u0435.";this.data.h.cortana_say_4="\u0417\u0430\u0439\u0434\u0435\u043c \u043a\u043e \u043c\u043d\u0435 \u0432 \u043b\u0430\u0432\u043a\u0443...";
this.data.h.cortana_say_5="\u0422\u0430\u043a\u0441... \u0433\u0434\u0435-\u0442\u043e \u0442\u0443\u0442...\n\u0410-\u0430-\u0430, \u0432\u043e\u0442 \u043e\u043d\u043e, \u0437\u0430\u0431\u0438\u0440\u0430\u0439.";this.data.h.cortana_say_6="\u041f\u0440\u043e\u0441\u0442\u0438, \u043d\u043e \u044f \u0438 \u0442\u0430\u043a \u0441 \u0442\u043e\u0431\u043e\u0439 \u0437\u0430\u0434\u0435\u0440\u0436\u0430\u043b\u0441\u044f.\n\u041a\u0430\u043a \u0442\u043e\u043b\u044c\u043a\u043e \u043c\u044b \u043f\u0440\u0438\u0431\u044b\u043b\u0438 \u0432 \u0433\u043e\u0440\u043e\u0434 \u044f \u043e\u0442\u043f\u0440\u0430\u0432\u0438\u043b \u0433\u043e\u043d\u0446\u0430 \u043a \u0442\u0432\u043e\u0438\u043c \u0434\u0440\u0443\u0437\u044c\u044f\u043c \u0433\u0432\u0430\u0440\u0434\u0435\u0439\u0446\u0430\u043c. \n\u041e\u043d\u0438 \u0442\u0430\u043c \u0440\u0430\u0437\u0431\u0435\u0440\u0443\u0442\u0441\u044f \u0447\u0442\u043e \u0441 \u0442\u043e\u0431\u043e\u0439 \u0434\u0435\u043b\u0430\u0442\u044c \u0434\u0430\u043b\u044c\u0448\u0435...";
this.data.h.cortana_say_7="\u041a\u0441\u0442\u0430\u0442\u0438, \u0437\u0430\u0445\u043e\u0434\u0438 \u043a\u043e \u043c\u043d\u0435 \u0432 \u043b\u0430\u0432\u043a\u0443 \u0435\u0441\u043b\u0438 \u043f\u043e\u044f\u0432\u044f\u0442\u0441\u044f \u043b\u0438\u0448\u043d\u0438\u0435 \u0434\u0435\u043d\u044c\u0436\u0430\u0442\u0430. \n\u041f\u043e\u0434\u0431\u0435\u0440\u0435\u043c \u0442\u0435\u0431\u0435 \u0447\u0442\u043e-\u043d\u0438\u0431\u0443\u0434\u044c \u043f\u043e\u0441\u043e\u043b\u0438\u0434\u043d\u0435\u0435! \n\u041f\u043e\u043a\u0430!";
this.data.h.cortana_say_8=", \u0432\u043e\u0442 \u0442\u044b \u0433\u0434\u0435. \u041a\u0430\u043a \u0442\u043e\u043b\u044c\u043a\u043e \u044f \u0443\u0437\u043d\u0430\u043b\u0430, \u0447\u0442\u043e \n\u043f\u0440\u043e\u0438\u0437\u043e\u0448\u043b\u043e \u2014 \u0441\u0440\u0430\u0437\u0443 \u043f\u043e\u0441\u043f\u0435\u0448\u0438\u043b\u0430 \u043a \u0442\u0435\u0431\u0435.\n... \u042d\u0439, \u0447\u0435\u0433\u043e \u0442\u044b \u0442\u0430\u043a \u043d\u0430 \u043c\u0435\u043d\u044f \u043f\u043e\u0434\u043e\u0437\u0440\u0438\u0442\u0435\u043b\u044c\u043d\u043e \u0441\u043c\u043e\u0442\u0440\u0438\u0448\u044c?";
this.data.h.cortana_say_9="\u041d\u0435 \u043f\u043e\u043c\u043d\u0438\u0448\u044c \u043c\u0435\u043d\u044f?! \u0412\u043e \u0434\u0435\u043b\u0430... \u042d\u0442\u043e \u0436\u0435 \u044f, \u041c\u044d\u0433. \n\u041c\u044b \u0441 \u0442\u043e\u0431\u043e\u0439 \u0432\u043c\u0435\u0441\u0442\u0435 3 \u0433\u043e\u0434\u0430 \u0441\u043b\u0443\u0436\u0438\u043b\u0438 \u0432 \u0413\u0432\u0430\u0440\u0434\u0438\u0438.\n...\u0414\u043e\u043b\u0436\u043d\u043e \u0431\u044b\u0442\u044c, \u0442\u0435\u0431\u0435 \u043f\u0430\u043c\u044f\u0442\u044c \u0432\u044b\u0448\u0438\u0431\u043b\u043e, \u0431\u044b\u0432\u0430\u0435\u0442.";
this.data.h.cortana_say_10="\u0413\u0432\u0430\u0440\u0434\u0438\u044f \u043f\u043e\u0440\u0443\u0447\u0438\u043b\u0430 \u043c\u043d\u0435 \u0441\u043e\u0431\u0440\u0430\u0442\u044c \u043e\u0442\u0440\u044f\u0434. \u041d\u0430\u0441 \u043e\u0442\u043f\u0440\u0430\u0432\u043b\u044f\u044e\u0442 \n\u043d\u0430 \u0432\u043e\u0441\u0442\u043e\u043a \u0441 \u0437\u0430\u0434\u0430\u043d\u0438\u0435\u043c \u043d\u0430\u0439\u0442\u0438 \u043b\u043e\u0433\u043e\u0432\u043e \u042d\u043b\u044c\u043e\u0434\u0434\u0443\u0440\u0430.\n\u0418 \u0442\u044b \u043f\u0435\u0440\u0432\u044b\u0439 \u0432 \u043c\u043e\u0435\u043c \u0441\u043f\u0438\u0441\u043a\u0435 \u043d\u0430 \u0432\u0441\u0442\u0443\u043f\u043b\u0435\u043d\u0438\u0435.";
this.data.h.cortana_say_11="\u0412\u044b\u0431\u043e\u0440\u0430 \u0443 \u0442\u0435\u0431\u044f, \u043a\u0441\u0442\u0430\u0442\u0438, \u043d\u0435\u0442. \u0418\u0434\u0435\u043c, \u043d\u0435 \u0431\u0443\u0434\u0435\u043c \u0442\u0435\u0440\u044f\u0442\u044c \u0432\u0440\u0435\u043c\u044f.";this.data.h.cortana_say_12="\u041d\u0430\u043c \u043d\u0443\u0436\u043d\u043e \u0432 \u0446\u0435\u043d\u0442\u0440\u0430\u043b\u044c\u043d\u0443\u044e \u0447\u0430\u0441\u0442\u044c \u0433\u043e\u0440\u043e\u0434\u0430.";
this.data.h.cortana_say_13="\u042d\u043b\u044c\u043e\u0434\u0434\u0443\u0440 \u2014 \u043c\u043e\u0433\u0443\u0449\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0439 \u041a\u043e\u043b\u0434\u0443\u043d. \n\u041d\u0430\u043c \u043f\u043e\u043d\u0430\u0434\u043e\u0431\u0438\u0442\u0441\u044f \u043c\u0430\u0433\u0438\u044f, \u0447\u0442\u043e\u0431\u044b \u043d\u0430\u0439\u0442\u0438 \u0435\u0433\u043e.";this.data.h.cortana_say_14="\u0412 \u0420\u0438\u0432\u0435\u0440\u0444\u043e\u0440\u0442\u0435, \u043a\u0430\u043a \u0440\u0430\u0437 \u0435\u0441\u0442\u044c \u043c\u0430\u0433\u0438\u0447\u0435\u0441\u043a\u0430\u044f \u043b\u0430\u0432\u043a\u0430, \u0432 \n\u043a\u043e\u0442\u043e\u0440\u043e\u0439 \u0440\u0430\u0431\u043e\u0442\u0430\u0435\u0442 \u043c\u0435\u0441\u0442\u043d\u044b\u0439 \u043a\u043e\u043b\u0434\u0443\u043d \u0414\u0443\u0440\u0438\u043d. \n\u0417\u0430\u0439\u0434\u0435\u043c \u043a \u043d\u0435\u043c\u0443.";
this.data.h.cortana_say_15="\u0410 \u0432\u043e\u0442 \u0438 \u043e\u043d\u0430, \u0438\u0434\u0435\u043c...";this.data.h.cortana_say_16="\u041f\u0440\u0438\u0432\u0435\u0442\u0441\u0442\u0432\u0443\u044e \u0412\u0430\u0441, \u043d\u0435\u0437\u043d\u0430\u043a\u043e\u043c\u0446\u044b! \n\u042f \u043e\u0447\u0435\u043d\u044c \u0441\u043e\u0436\u0430\u043b\u0435\u044e, \u043d\u043e \u043b\u0430\u0432\u043a\u0430 \u0437\u0430\u043a\u0440\u044b\u0442\u0430 \u043f\u043e \u043f\u0440\u0438\u0447\u0438\u043d\u0435 \u043d\u0430\u043b\u0438\u0447\u0438\u044f \n\u0423\u0416\u0410\u0421\u041d\u042b\u0425 \u0442\u0432\u0430\u0440\u0435\u0439 \u0432 \u043f\u043e\u0434\u0432\u0430\u043b\u0435.";
this.data.h.cortana_say_17="\u041d\u0438\u043a\u0430\u043a\u0438\u0435 \u044f\u0434\u044b \u043d\u0430 \u043d\u0438\u0445 \u043d\u0435 \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u044e\u0442! \n\u0421\u0435\u0439\u0447\u0430\u0441 \u044f \u043e\u0447\u0435\u043d\u044c \u0437\u0430\u043d\u044f\u0442 \u0441\u043e\u0437\u0434\u0430\u043d\u0438\u0435\u043c \u0437\u0430\u043a\u043b\u0438\u043d\u0430\u043d\u0438\u044f \u0434\u043b\u044f \u0438\u0445 \u0443\u043d\u0438\u0447\u0442\u043e\u0436\u0435\u043d\u0438\u044f!\n\u041f\u043e\u043a\u0430 \u043d\u0435 \u043c\u043e\u0433\u0443 \u0432\u0430\u043c \u043d\u0438\u0447\u0435\u043c \u043f\u043e\u043c\u043e\u0447\u044c.";
this.data.h.cortana_say_18="\u041c\u044b \u043c\u043e\u0436\u0435\u043c \u043f\u043e\u0434\u0441\u043e\u0431\u0438\u0442\u044c \u0412\u0430\u043c \u0432 \u0440\u0435\u0448\u0435\u043d\u0438\u0438 \u0434\u0430\u043d\u043d\u043e\u0439 \u0423\u0416\u0410\u0421\u041d\u041e\u0419 \u043f\u0440\u043e\u0431\u043b\u0435\u043c\u044b. \n\u0412 \u043e\u0431\u043c\u0435\u043d \u043c\u044b \u043b\u0438\u0448\u044c \u0437\u0430\u0434\u0430\u0434\u0438\u043c \u0432\u0430\u043c \u043f\u0430\u0440\u0443 \u0432\u043e\u043f\u0440\u043e\u0441\u043e\u0432.";
this.data.h.cortana_say_19="\u041f\u043e\u043c\u043e\u0436\u0435\u0442\u0435? \u0421\u043e\u043c\u043d\u0438\u0442\u0435\u043b\u044c\u043d\u043e, \u0442\u0430\u043c \u043e\u043d\u0438 \u0442\u0430\u043a\u0438\u0435 \u0423\u0416\u0410\u0421\u041d\u042b\u0415!\n\u041f\u043e\u0439\u0434\u0435\u043c\u0442\u0435 \u043f\u043e\u043a\u0430\u0436\u0443!";this.data.h.cortana_say_20="\u0412\u041e\u0422! \u0412\u041e\u0422 \u044d\u0442\u0430 \u0441\u0442\u0440\u0430\u0441\u0442\u044c!\n\u0423\u0431\u0435\u0439\u0442\u0435 \u042d\u0422\u041e! \u042f \u0432\u0441\u0435, \u0447\u0442\u043e \u0437\u0430\u0445\u043e\u0442\u0438\u0442\u0435 \u0440\u0430\u0441\u0441\u043a\u0430\u0436\u0443!";
this.data.h.cortana_say_21="\u0414\u0430 \u044d\u0442\u043e \u0436\u0435 \u0432\u0441\u0435\u0433\u043e-\u043b\u0438\u0448\u044c \u043a\u0440\u044b\u0441\u0430! \u0421\u0435\u0439\u0447\u0430\u0441 \u043c\u044b \u0435\u0435 \u0440\u0430\u0437\u0434\u0430\u0432\u0438\u043c!";this.data.h.cortana_say_22="\u0422\u044b \u0431\u044b\u043b \u043e\u0434\u043d\u0438\u043c \u0438\u0437 \u043b\u0443\u0447\u0448\u0438\u0445 \u0441\u0440\u0435\u0434\u0438 \u043d\u0430\u0441.";this.data.h.cortana_say_23="\u0421 \u043a\u0440\u044b\u0441\u043e\u0439 \u0442\u044b \u043b\u0435\u0433\u043a\u043e \u0441\u043f\u0440\u0430\u0432\u0438\u0448\u044c\u0441\u044f. \u0414\u0430\u0436\u0435 \u0441 \u0442\u0430\u043a\u043e\u0439 \u043e\u0442\u043a\u043e\u0440\u043c\u043b\u0435\u043d\u043d\u043e\u0439.";
this.data.h.cortana_say_24="\u0410 \u0442\u0435\u043f\u0435\u0440\u044c \u043d\u0435 \u0437\u0435\u0432\u0430\u0439! \u0410\u0442\u0430\u043a\u0443\u0439!";this.data.h.cortana_say_25="\u041b\u0435\u0433\u043a\u043e! \u0415\u0449\u0435 \u0443\u0434\u0430\u0440 \u0438 \u0435\u0439 \u043a\u043e\u043d\u0435\u0446!";this.data.h.cortana_say_26="\u041b\u0435\u0433\u043a\u043e\u0442\u043d\u044f! \n\u0413\u043e\u0440\u043e\u0434\u0441\u043a\u0438\u043c \u0441\u043e\u0432\u0435\u0442\u043e\u043c \u0431\u044b\u043b\u0430 \u043d\u0430\u0437\u043d\u0430\u0447\u0435\u043d\u0430 \u043d\u0430\u0433\u0440\u0430\u0434\u0430 \u0437\u0430 \u0443\u0431\u0438\u0439\u0441\u0442\u0432\u043e \u0432\u0441\u044f\u043a\u0438\u0445 \u0442\u0432\u0430\u0440\u0435\u0439!";
this.data.h.cortana_say_27="\u0417\u0430\u0431\u0438\u0440\u0430\u0439 \u0435\u0435, \u0437\u0430\u043e\u0434\u043d\u043e \u0438 \u0445\u0432\u043e\u0441\u0442 \u043a\u0440\u044b\u0441\u044e\u043a\u0430 \u043d\u0435 \u0437\u0430\u0431\u0443\u0434\u044c \u0434\u043b\u044f \u0434\u043e\u043a\u0430\u0437\u0430\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u0430. \n\u041c\u0430\u0433 \u0431\u0443\u0434\u0435\u0442 \u043e\u0447\u0435\u043d\u044c \u0440\u0430\u0434.";this.data.h.cortana_say_28="\u041f\u043e\u0439\u0434\u0435\u043c \u043a \u041c\u0430\u0433\u0443, \u043e\u0431\u0440\u0430\u0434\u0443\u0435\u043c \u0435\u0433\u043e!";
this.data.h.cortana_say_29="\u0417\u0430\u0445\u043e\u0434\u0438 \u0432 \u043b\u0430\u0432\u043a\u0443.";this.data.h.cortana_say_30="\u0410-\u0430-\u0430, \u041d\u0415-\u0415-\u0415-\u0415\u0422.\n\u041e\u0439, \u0430\u0445, \u044d\u0442\u043e \u0432\u044b. \u0411\u044b\u0441\u0442\u0440\u043e, \u043e\u0434\u043d\u0430\u043a\u043e!\n\u0427\u0435\u043c \u043f\u043e\u0440\u0430\u0434\u0443\u0435\u0442\u0435?";this.data.h.cortana_say_31="\u041c\u044b \u0440\u0430\u0437\u043e\u0431\u0440\u0430\u043b\u0438\u0441\u044c \u0441 \u0432\u0430\u0448\u0435\u0439 \u043f\u0440\u043e\u0431\u043b\u0435\u043c\u043e\u0439. \n\u0412\u0430\u0448\u0430 \u043e\u0447\u0435\u0440\u0435\u0434\u044c \u2014 \u043e\u0442\u0432\u0435\u0442\u044c\u0442\u0435 \u043d\u0430\u043c \u043d\u0430 \u0432\u043e\u043f\u0440\u043e\u0441:\n - \u041a\u0430\u043a \u043d\u0430\u0439\u0442\u0438 \u041b\u0438\u0447\u0430?";
this.data.h.cortana_say_32="\u0427\u0435, \u043f\u0440\u0430\u0432\u0434\u0430? \u0420\u0430\u0437\u043e\u0431\u0440\u0430\u043b\u0438\u0441\u044c? \u0419\u0430\u0445-\u0443-\u0443!!!\n\u0410 \u0442\u043e\u043b\u044c\u043a\u043e \u0441\u043f\u0435\u0440\u0432\u0430 \u0434\u043e\u043a\u0430\u0436\u0438\u0442\u0435!";this.data.h.cortana_say_33="\u0424\u0443-\u0443-\u0443, \u043d\u0443 \u0438 \u0433\u0430\u0434\u043e\u0441\u0442\u044c! \u041f\u043e\u0445\u043e\u0436\u0435, \u0432\u044b \u0412\u0415\u041b\u0418\u041a\u0418\u0415 \u0432\u043e\u0438\u043d\u044b! \n\u0422\u0435\u043f\u0435\u0440\u044c \u044f \u0441\u043d\u043e\u0432\u0430 \u043c\u043e\u0433\u0443 \u0432\u0430\u0440\u0438\u0442\u044c \u0437\u0435\u043b\u044c\u044f!";
this.data.h.cortana_say_34="\u0410\u0445 \u0434\u0430, \u0432\u044b \u0436\u0435 \u0445\u043e\u0442\u0435\u043b\u0438 \u0443\u0437\u043d\u0430\u0442\u044c \u043f\u0440\u043e \u042d\u043b\u044c\u043e\u0434\u0434\u0443\u0440\u0430. \n\u0415\u0441\u0442\u044c \u0443 \u043c\u0435\u043d\u044f \u043a\u043e\u0435-\u043a\u0430\u043a\u0430\u044f \u0438\u043d\u0444\u043e\u0440\u043c\u0430\u0446\u0438\u044f!";this.data.h.cortana_say_35="\u0412\u0430\u043c \u043d\u0443\u0436\u0435\u043d \u043d\u0430\u0435\u043c\u043d\u0438\u043a \u043f\u043e \u0438\u043c\u0435\u043d\u0438 \u0413\u0430\u043d\u0441. \u041d\u0435 \u0442\u0430\u043a \u0434\u0430\u0432\u043d\u043e \u043e\u043d \u043f\u0440\u0438\u043d\u0435\u0441 \u043c\u043d\u0435 \u0432 \n\u043b\u0430\u0432\u043a\u0443 \u043d\u0430 \u043f\u0440\u043e\u0434\u0430\u0436\u0443 \u0413\u043e\u0431\u043b\u0438\u043d\u0441\u043a\u0438\u0439 \u0410\u043c\u0443\u043b\u0435\u0442. \u0422\u0430\u043a\u0438\u0435 \u0430\u043c\u0443\u043b\u0435\u0442\u044b \u043d\u043e\u0441\u044f\u0442 \n\u0442\u043e\u043b\u044c\u043a\u043e \u043f\u0440\u0438\u0441\u043b\u0443\u0436\u043d\u0438\u043a\u0438 \u0442\u0435\u043c\u043d\u043e\u0433\u043e \u043a\u043e\u043b\u0434\u0443\u043d\u0430.";
this.data.h.cortana_say_36="\u0418... \u0418 \u0432\u0441\u0435? \n\u041d-\u0434\u0430.. \u042f \u0442\u043e \u0434\u0443\u043c\u0430\u043b\u0430, \u043e\u043d \u0441\u0435\u0439\u0447\u0430\u0441 \u043a\u0430\u043a \u043d\u0430\u043a\u043e\u043b\u0434\u0443\u0435\u0442 \u043d\u0430\u043c \u0447\u0442\u043e-\u043d\u0438\u0431\u0443\u0434\u044c \u043a\u0440\u0443\u0442\u043e\u0435.\n\u041d\u043e, \u043d\u0430\u043c \u043f\u043e\u0432\u0435\u0437\u043b\u043e. \u042f \u0437\u043d\u0430\u044e \u0413\u0430\u043d\u0441\u0430 \u0438 \u0434\u0430\u0436\u0435 \u0437\u043d\u0430\u044e \u0433\u0434\u0435 \u043f\u0440\u0438\u043c\u0435\u0440\u043d\u043e \u0435\u0433\u043e \u0438\u0441\u043a\u0430\u0442\u044c.";
this.data.h.cortana_say_37="\u0418\u0434\u0435\u043c...";this.data.h.cortana_say_38="\u041d\u043e, \u0434\u043b\u044f \u043d\u0430\u0447\u0430\u043b\u0430, \u0434\u0430\u0432\u0430\u0439 \u0437\u0430\u0433\u043b\u044f\u043d\u0435\u043c \u0432 \u0411\u0435\u0439\u043b\u0443. \n\u0422\u044b \u0437\u0430\u0440\u0430\u0431\u043e\u0442\u0430\u043b \u0434\u0435\u043d\u044c\u0436\u0430\u0442. \n\u041c\u043e\u0436\u043d\u043e \u043f\u0440\u0438\u0441\u043c\u043e\u0442\u0440\u0435\u0442\u044c \u043e\u0431\u043d\u043e\u0432\u043a\u0438. \u0410\u0442\u043e \u043d\u0430 \u043e\u0431\u043e\u0440\u0432\u0430\u043d\u0446\u0430 \u043f\u043e\u0445\u043e\u0436.";
this.data.h.cortana_say_39="\u041d\u0435 \u043e\u0442\u0441\u0442\u0430\u0432\u0430\u0439...";this.data.h.cortana_say_40="\u0417\u0434\u0440\u0430\u0432\u0441\u0442\u0432\u0443\u0439\u0442\u0435, \u0423\u0432\u0430\u0436\u0430\u0435\u043c\u044b\u0435! \n\u0427\u0435\u0433\u043e \u0438\u0437\u0432\u043e\u043b\u0438\u0442\u0435?";this.data.h.cortana_say_41="\u041f\u043e\u043a\u0430\u0436\u0438 \u043d\u0430\u043c \u0442\u043e\u0432\u0430\u0440.";this.data.h.cortana_say_42="\u041f\u043e\u0441\u043c\u043e\u0442\u0440\u0438\u0442\u0435, \u043a\u0430\u043a\u0438\u0435 \u0432\u0435\u043b\u0438\u043a\u043e\u043b\u0435\u043f\u043d\u044b\u0435 \u0448\u043b\u0435\u043c\u044b \u0443 \u043c\u0435\u043d\u044f \u0435\u0441\u0442\u044c!";
this.data.h.cortana_say_43="\u0418\u043b\u0438 \u0432\u043e\u0442! \u041b\u0443\u0447\u0448\u0430\u044f \u0437\u0430\u0449\u0438\u0442\u0430 \u0434\u043b\u044f \u0432\u043e\u0438\u043d\u0430!";this.data.h.cortana_say_44="\u0421\u043c\u043e\u0442\u0440\u0438, \u043e\u0442\u043b\u0438\u0447\u043d\u0430\u044f \u0437\u0430\u0449\u0438\u0442\u0430! \u0418 \u043f\u043e \u0434\u0435\u043d\u044c\u0433\u0430\u043c \u043f\u0440\u0438\u0435\u043c\u043b\u0435\u043c\u043e. \n\u041f\u043e\u043a\u0443\u043f\u0430\u0439!";
this.data.h.cortana_say_45="\u041e\u0442\u043b\u0438\u0447\u043d\u044b\u0439 \u0432\u044b\u0431\u043e\u0440!\n\u0427\u0442\u043e-\u0442\u043e \u0435\u0449\u0435?";this.data.h.cortana_say_46="\u041d\u0435\u0442, \u043d\u0430\u043c \u043f\u043e\u0440\u0430.\n\u0418\u0434\u0435\u043c... \u041d\u0430\u0439\u0434\u0435\u043c \u0413\u0430\u043d\u0441\u0430.";this.data.h.cortana_say_47="\u041e\u0442\u043a\u0440\u043e\u0439 \u043a\u0430\u0440\u0442\u0443.";this.data.h.cortana_say_48="\u0421\u0435\u0432\u0435\u0440\u043d\u044b\u0439 \u0420\u0438\u0432\u0435\u0440\u0444\u043e\u0440\u0442, \u0438\u0434\u0435\u043c...";
this.data.h.cortana_say_49="\u0413\u0430\u043d\u0441 \u0447\u0430\u0449\u0435 \u0432\u0441\u0435\u0433\u043e \u0437\u0430\u0432\u0438\u0441\u0430\u0435\u0442 \u0432 \u0442\u0430\u0432\u0435\u0440\u043d\u0435. \n\u041f\u043e\u0439\u0434\u0435\u043c, \u0437\u0430\u0433\u043b\u044f\u043d\u0435\u043c \u0442\u0443\u0434\u0430.";this.data.h.cortana_say_50="\u0410 \u0432\u043e\u0442 \u0438 \u0442\u0430\u0432\u0435\u0440\u043d\u0430, \u0437\u0430\u0445\u043e\u0434\u0438\u043c.";this.data.h.cortana_say_51=
"\u0421\u0442\u0440\u0430\u043d\u043d\u043e, \u043e\u0431\u044b\u0447\u043d\u043e \u0432 \u0442\u0430\u0432\u0435\u0440\u043d\u0435 \u0432 \u044d\u0442\u043e \u0432\u0440\u0435\u043c\u044f \u043a\u0443\u0447\u0430 \u043b\u044e\u0434\u0435\u0439. \n\u0413\u0434\u0435 \u0436\u0435 \u0432\u0441\u0435? \n- \u042d\u0419! \u0425\u041e\u0417\u042f\u0418\u041d!!";this.data.h.cortana_say_52="\u041f\u0440\u0438\u0432\u0435\u0442, \u0438\u0437\u0432\u0438\u043d\u0438\u0442\u0435, \u043d\u043e \u0442\u0430\u0432\u0435\u0440\u043d\u0430 \u0437\u0430\u043a\u0440\u044b\u0442\u0430.";
this.data.h.cortana_say_53="\u041f\u043e\u0447\u0435\u043c\u0443 \u0437\u0430\u043a\u0440\u044b\u0442\u0430? \n\u0427\u0442\u043e \u0441\u043b\u0443\u0447\u0438\u043b\u043e\u0441\u044c?";this.data.h.cortana_say_54="\u041f\u0430\u0443\u043a\u0438 \u043d\u0430 \u043a\u0443\u0445\u043d\u0435 \u0437\u0430\u0432\u0435\u043b\u0438\u0441\u044c, \u0433\u0438\u0433\u0430\u043d\u0442\u0441\u043a\u0438\u0435. \n\u041d\u0435 \u043c\u043e\u0436\u0435\u043c \u0440\u0430\u0431\u043e\u0442\u0430\u0442\u044c...";
this.data.h.cortana_say_55="\u0427\u0442\u043e \u0437\u0430 \u043d\u0430\u043f\u0430\u0441\u0442\u044c \u0443 \u0432\u0441\u0435\u0445. \u0421\u043d\u0430\u0447\u0430\u043b\u0430 \u0443 \u043a\u043e\u043b\u0434\u0443\u043d\u0430, \u0442\u0435\u043f\u0435\u0440\u044c \u0442\u0443\u0442. \n\u041c\u044b \u043f\u043e\u043c\u043e\u0436\u0435\u043c \u0442\u0435\u0431\u0435. \u041d\u043e \u0437\u0430 \u044d\u0442\u043e \u0441 \u0442\u0435\u0431\u044f \u043f\u0440\u0438\u0447\u0438\u0442\u0430\u0435\u0442\u0441\u044f!";
this.data.h.cortana_say_56="\u041a\u043e\u043d\u0435\u0447\u043d\u043e! \u041a\u043e\u043d\u0435\u0447\u043d\u043e! \u0412\u0441\u0435 \u0447\u0442\u043e \u0443\u0433\u043e\u0434\u043d\u043e, \u0442\u043e\u043b\u044c\u043a\u043e \u043f\u043e\u043c\u043e\u0433\u0438\u0442\u0435! \n\u041f\u043e\u0439\u0434\u0435\u043c \u043f\u043e\u043a\u0430\u0436\u0443 \u043f\u0430\u0443\u043a\u0430!";this.data.h.cortana_say_57="\u0412\u041e\u0422 \u041e\u041d!";this.data.h.cortana_say_58="\u041e\u0433\u043e! \u0412\u044b\u0433\u043b\u044f\u0434\u0438\u0442 \u043e\u043d \u043f\u043e\u0441\u0442\u0440\u0430\u0448\u043d\u0435\u0435 \u0442\u043e\u0439 \u043a\u0440\u044b\u0441\u044b. \n\u041d\u0430\u043f\u0430\u0434\u0430\u0439!";
this.data.h.cortana_say_59="\u0412 \u0430\u0442\u0430\u043a\u0443!";this.data.h.cortana_say_60="\u0415\u0449\u0435 \u0443\u0434\u0430\u0440!!";this.data.h.cortana_say_61="\u0411\u0435\u0439, \u043d\u0435 \u043e\u0441\u0442\u0430\u043d\u0430\u0432\u043b\u0438\u0432\u0430\u0439\u0441\u044f!";this.data.h.cortana_say_62="\u041e \u043d\u0435\u0442! \u041e\u043d \u0441\u043b\u0438\u0448\u043a\u043e\u043c \u0441\u0438\u043b\u0435\u043d!\n\u041e\u0442\u0441\u0442\u0443\u043f\u0430\u0435\u043c!";this.data.h.cortana_say_63=
"\u041d-\u0434\u0430... \u041d\u0430\u0432\u0430\u043b\u044f\u043b\u0438 \u0442\u0435\u0431\u0435, \u0431\u0440\u0430\u0442\u0435\u0446. \n\u041f\u043e\u0445\u043e\u0436\u0435, \u043f\u0440\u0438\u0448\u043b\u043e \u0432\u0440\u0435\u043c\u044f \u0442\u0440\u0435\u043d\u0438\u0440\u043e\u0432\u043a\u0438. \n\u0418\u0434\u0435\u043c..";this.data.h.cortana_say_64="\u0416\u043c\u0438...";this.data.h.cortana_say_65="\u0421\u044e\u0434\u0430.";this.data.h.cortana_say_66="\u041f\u0440\u043e\u0432\u0435\u0434\u0438 \u0442\u0440\u0435\u043d\u0438\u0440\u043e\u0432\u043a\u0443.";
this.data.h.cortana_say_67="\u0422\u044b \u0441\u0442\u0430\u043d\u043e\u0432\u0438\u0448\u044c\u0441\u044f \u0441\u0438\u043b\u044c\u043d\u0435\u0435 \u0441 \u043a\u0430\u0436\u0434\u043e\u0439 \u0442\u0440\u0435\u043d\u0438\u0440\u043e\u0432\u043a\u043e\u0439.";this.data.h.cortana_say_68="\u0422\u0435\u043f\u0435\u0440\u044c \u0432\u043e\u0442 \u044d\u0442\u043e\u0442 \u043d\u0430\u0432\u044b\u043a \u0442\u0440\u0435\u043d\u0438\u0440\u0443\u0439.";this.data.h.cortana_say_69="\u041e\u0442\u043b\u0438\u0447\u043d\u043e, \u0442\u0440\u0435\u043d\u0438\u0440\u043e\u0432\u043a\u0443 \u043f\u0440\u043e\u0432\u0435\u043b\u0438.";
this.data.h.cortana_say_70="\u041f\u043e\u0439\u0434\u0435\u043c \u043a \u043f\u0430\u0443\u043a\u0443 \u0435\u0449\u0435 \u0440\u0430\u0437...";this.data.h.cortana_say_71="\u0412\u043e\u0442 \u0438 \u043e\u043d.";this.data.h.cortana_say_72="\u041d\u0430\u043f\u0430\u0434\u0430\u0439!";this.data.h.cortana_say_73="\u041d\u0430\u0447\u043d\u0438 \u0441 \u0438\u0437\u0443\u0447\u0435\u043d\u043d\u043e\u0433\u043e \u043f\u0440\u0438\u0435\u043c\u0430, \u0431\u0435\u0439!";this.data.h.cortana_say_74="\u0422\u0435\u043f\u0435\u0440\u044c \u0443\u0434\u0430\u0440!";
this.data.h.cortana_say_75="\u041a\u0430\u043a \u0436\u0435 \u043e\u043d \u0441\u0438\u043b\u0435\u043d, \u0431\u0435\u0439!";this.data.h.cortana_say_76="\u041e \u043d\u0435\u0442! \u041f\u0430\u0443\u043a \u043e\u043f\u044f\u0442\u044c \u0442\u0435\u0431\u044f \u043e\u0434\u043e\u043b\u0435\u043b... \u041f\u043e\u0445\u043e\u0436\u0435, \u0431\u0435\u0437 \u043c\u0430\u0433\u0438\u0438 \u043d\u0435 \u043e\u0431\u043e\u0439\u0442\u0438\u0441\u044c.";this.data.h.cortana_say_77="\u0422\u0435\u043f\u0435\u0440\u044c \u043f\u043e\u043f\u0440\u043e\u0431\u0443\u0435\u043c \u043d\u0430\u043f\u0430\u0441\u0442\u044c \u043d\u0430 \u043f\u0430\u0443\u043a\u0430 \u0438 \u043f\u0440\u0438\u043c\u0435\u043d\u0438\u043c \u043c\u0430\u0433\u0438\u044e!";
this.data.h.cortana_say_78="\u041e\u043d \u0443\u0436\u0435 \u0436\u0434\u0435\u0442 \u0442\u0435\u0431\u044f.";this.data.h.cortana_say_79="\u041d\u0430\u043f\u0430\u0434\u0430\u0439!";this.data.h.cortana_say_80="\u041d\u0430\u043c \u043d\u0443\u0436\u043d\u044b \u043c\u0430\u0433\u0438\u0447\u0435\u0441\u043a\u0438\u0435 \u0441\u0432\u0438\u0442\u043a\u0438, \u0432\u0437\u044f\u0442\u044c \u0438\u0445 \u043c\u043e\u0436\u043d\u043e \u0442\u0443\u0442.";this.data.h.cortana_say_81="\u0411\u0435\u0440\u0438 \u0441\u0432\u0438\u0442\u043e\u043a \u043c\u043e\u043b\u043d\u0438\u0438. \u041c\u043e\u0449\u043d\u0430\u044f \u0432\u0435\u0449\u044c.";
this.data.h.cortana_say_82="\u041e\u0442\u043b\u0438\u0447\u043d\u043e, \u0432\u0435\u0440\u043d\u0435\u043c\u0441\u044f \u043a \u043d\u0430\u0448\u0435\u043c\u0443 \u043f\u0430\u0443\u043a\u0443.";this.data.h.cortana_say_83="\u0428\u0430\u0440\u0430\u0445\u043d\u0438 \u0435\u0433\u043e!";this.data.h.cortana_say_84="\u0410 \u0442\u0435\u043f\u0435\u0440\u044c \u0443\u0434\u0430\u0440!";this.data.h.cortana_say_85="\u041f\u0440\u0438\u0435\u043c!";this.data.h.cortana_say_86="\u0414\u043e\u0431\u0438\u0432\u0430\u0439 \u0433\u0430\u0434\u0430!";
this.data.h.cortana_say_87="\u0423\u0444\u0444, \u043d\u0430\u043a\u043e\u043d\u0435\u0446-\u0442\u043e! \u041d\u0435 \u0437\u0430\u0431\u0443\u0434\u044c \u043d\u0430\u0433\u0440\u0430\u0434\u0443 \u0437\u0430 \u044d\u0442\u0443 \u0442\u0432\u0430\u0440\u044c.";this.data.h.cortana_say_88="\u041f\u043e\u0439\u0434\u0435\u043c, \u043e\u0431\u0440\u0430\u0434\u0443\u0435\u043c \u0445\u043e\u0437\u044f\u0438\u043d\u0430 \u0442\u0430\u0432\u0435\u0440\u043d\u044b.";this.data.h.cortana_say_89="\u041d\u0435 \u043e\u0442\u0441\u0442\u0430\u0432\u0430\u0439.";
this.data.h.cortana_say_90="\u041f\u0440\u0438\u0432\u0435\u0442 \u0441\u043d\u043e\u0432\u0430! \u041d\u0443, \u043d\u0443 \u0447\u0442\u043e \u0442\u0430\u043c? \u0427\u0442\u043e \u0442\u0430\u043c \u0441 \u043f\u0430\u0443\u043a\u043e\u043c?";this.data.h.cortana_say_91="\u0412\u0430\u0439! \u0427\u0435\u0441\u0442\u043d\u043e \u0433\u043e\u0432\u043e\u0440\u044f \u0438 \u043d\u0435 \u043d\u0430\u0434\u0435\u044f\u043b\u0441\u044f, \u0432\u044b \u043e\u0447\u0435\u043d\u044c \u043c\u0435\u043d\u044f \u0432\u044b\u0440\u0443\u0447\u0438\u043b\u0438. \n\u0422\u0430\u0432\u0435\u0440\u043d\u0430 \u0431\u0443\u0434\u0435\u0442 \u043e\u0442\u043a\u0440\u044b\u0442\u0430 \u0441\u0435\u0433\u043e\u0434\u043d\u044f \u0436\u0435!";
this.data.h.cortana_say_92="\u0420\u0430\u0434\u044b \u043f\u043e\u043c\u043e\u0447\u044c. \u041d\u0430\u043b\u0435\u0439 \u043d\u0430\u043c \u0441\u0432\u043e\u0435\u0433\u043e \u043b\u0443\u0447\u0448\u0435\u0433\u043e \u043f\u0438\u0432\u0430. \n\u041c\u044b \u043f\u043e\u0441\u0438\u0434\u0438\u043c, \u043f\u043e\u0434\u043e\u0436\u0434\u0435\u043c \u0434\u0440\u0443\u0433\u0430.";this.data.h.cortana_say_93="*\u043f\u0440\u043e\u0448\u043b\u043e 3 \u0447\u0430\u0441\u0430*\n\u041f\u0440\u0438\u0432\u0435\u0442, \u044f \u0441\u043b\u044b\u0448\u0430\u043b \u0432\u044b \u043c\u0435\u043d\u044f \u0438\u0441\u043a\u0430\u043b\u0438?";
this.data.h.cortana_say_94="\u0417\u0434\u0440\u0430\u0432\u0441\u0442\u0432\u0443\u0439, \u0413\u0430\u043d\u0441. \n\u0418\u0441\u043a\u0430\u043b\u0438. \u0423 \u043d\u0430\u0441 \u0435\u0441\u0442\u044c \u043f\u0430\u0440\u0430 \u0432\u043e\u043f\u0440\u043e\u0441\u043e\u0432 \u043a \u0442\u0435\u0431\u0435.";this.data.h.cortana_say_95="\u041a\u043e\u043d\u0435\u0447\u043d\u043e! \u0412\u044b \u0436\u0435 \u043f\u043e\u043c\u043e\u0433\u043b\u0438 \u043e\u0442\u043a\u0440\u044b\u0442\u044c \u043c\u043e\u044e \u043b\u044e\u0431\u0438\u043c\u0443\u044e \u0442\u0430\u0432\u0435\u0440\u043d\u0443! \n\u041f\u043e\u043c\u043e\u0433\u0443, \u0447\u0435\u043c \u0441\u043c\u043e\u0433\u0443!";
this.data.h.cortana_say_96="\u0421\u043f\u0430\u0441\u0438\u0431\u043e. \u041d\u0430\u043c \u043d\u0443\u0436\u043d\u043e \u0437\u043d\u0430\u0442\u044c, \u0433\u0434\u0435 \u0442\u044b \u0432\u0437\u044f\u043b \u0413\u043e\u0431\u043b\u0438\u043d\u0441\u043a\u0438\u0439 \u0430\u043c\u0443\u043b\u0435\u0442, \n\u043a\u043e\u0442\u043e\u0440\u044b\u0439 \u043d\u0435\u0434\u0430\u0432\u043d\u043e \u043e\u0442\u043d\u0435\u0441 \u0432 \u043b\u0430\u0432\u043a\u0443 \u043a\u043e\u043b\u0434\u0443\u043d\u0443 \u0414\u0443\u0440\u0438\u043d\u0443?";
this.data.h.cortana_say_97="\u0410\u043c\u0443\u043b\u0435\u0442? \u0425\u043c...\n\u041d\u0430\u0448\u0435\u043b \u044f \u0435\u0433\u043e \u0432 \u0440\u0430\u0437\u0432\u0430\u043b\u0438\u043d\u0430\u0445 \u0421\u0442\u0430\u0440\u043e\u0433\u043e \u0424\u043e\u0440\u0442\u0430. \n\u042d\u0442\u043e \u043a \u0432\u043e\u0441\u0442\u043e\u043a\u0443 \u043e\u0442 \u0420\u0438\u0432\u0435\u0440\u0444\u043e\u0440\u0442\u0430.";this.data.h.cortana_say_98="\u041c\u044b \u0441 \u043e\u0442\u0440\u044f\u0434\u043e\u043c \u0438\u0441\u043a\u0430\u043b\u0438 \u0442\u0430\u043c \u0431\u0430\u043d\u0434\u0443 \u0440\u0430\u0437\u0431\u043e\u0439\u043d\u0438\u043a\u043e\u0432. \n\u041d\u0438\u043a\u043e\u0433\u043e, \u043f\u0440\u0430\u0432\u0434\u0430, \u0442\u0430\u043a \u0438 \u043d\u0435 \u043d\u0430\u0448\u043b\u0438. \u0417\u0430\u0442\u043e \u043d\u0430\u0448\u043b\u0438 \u0441\u0442\u043e\u044f\u043d\u043a\u0443 \u0413\u043e\u0431\u043b\u0438\u043d\u043e\u0432.\n \u041e\u0442\u0442\u0443\u0434\u0430 \u0438 \u0430\u043c\u0443\u043b\u0435\u0442.";
this.data.h.cortana_say_99="\u0421\u043f\u0430\u0441\u0438\u0431\u043e \u0437\u0430 \u0438\u043d\u0444\u043e\u0440\u043c\u0430\u0446\u0438\u044e, \u043c\u044b \u0443\u0437\u043d\u0430\u043b\u0438, \u0447\u0442\u043e \u043d\u0430\u043c \u043d\u0443\u0436\u043d\u043e. \n\u0423\u0434\u0430\u0447\u0438!";this.data.h.cortana_say_100="\u0423\u0434\u0430\u0447\u0438 \u0432\u0430\u043c, \u0434\u0440\u0443\u0437\u044c\u044f! \n\u041f\u0440\u043e\u0449\u0430\u0439\u0442\u0435.";this.data.h.cortana_say_101=
"\u0422\u0435\u043f\u0435\u0440\u044c \u043d\u0430\u043c \u043f\u0440\u0435\u0434\u0441\u0442\u043e\u0438\u0442 \u043d\u0435\u043b\u0435\u0433\u043a\u0438\u0439 \u043f\u0443\u0442\u044c. \n\u041d\u0430\u0434\u043e \u043d\u0435\u043c\u043d\u043e\u0433\u043e \u043f\u043e\u0434\u0433\u043e\u0442\u043e\u0432\u0438\u0442\u044c\u0441\u044f.";this.data.h.cortana_say_102="\u0427\u0442\u043e\u0431\u044b \u0442\u044b \u043d\u0435 \u0437\u0430\u0431\u044b\u0432\u0430\u043b, \u0447\u0442\u043e \u043d\u0430\u0434\u043e \u0434\u0435\u043b\u0430\u0442\u044c \u2014 \u0441\u043c\u043e\u0442\u0440\u0438, \n\u0432\u043e\u0442 \u0442\u0443\u0442 \u0441\u043f\u0438\u0441\u043e\u043a \u0442\u0435\u043a\u0443\u0449\u0438\u0445 \u0434\u0435\u043b. \u0412\u044b\u043f\u043e\u043b\u043d\u044f\u0439 \u0438\u0445. \n\u0410 \u044f \u043f\u043e\u043a\u0430 \u043e\u0442\u043b\u0443\u0447\u0443\u0441\u044c \u043f\u043e \u0434\u0435\u043b\u0430\u043c, \u0441\u043a\u043e\u0440\u043e \u0443\u0432\u0438\u0434\u0438\u043c\u0441\u044f!";
this.data.h.cortana_say_103="\u041f\u0430\u0443\u0447\u0438\u0439 \u043b\u0435\u0441. \u041d\u0430\u0437\u0432\u0430\u043d\u0438\u0435 \u0441\u0430\u043c\u043e \u0437\u0430 \u0441\u0435\u0431\u044f \u0433\u043e\u0432\u043e\u0440\u0438\u0442. \u0416\u0443\u0442\u043a\u043e\u0435 \u043c\u0435\u0441\u0442\u043e!\n \u041d\u0430\u0434\u043e \u043f\u0440\u043e\u0439\u0442\u0438 \u0435\u0433\u043e \u0441\u043a\u043e\u0440\u0435\u0435.";this.data.h.cortana_say_104="\u041c\u043d\u043e\u0433\u043e \u0432\u0441\u044f\u043a\u0438\u0445 \u0438\u0441\u0442\u043e\u0440\u0438\u0439 \u0445\u043e\u0434\u0438\u0442 \u043f\u0440\u043e \u043f\u0430\u0443\u0447\u044c\u044e \u043a\u043e\u0440\u043e\u043b\u0435\u0432\u0443. \u0425\u043e\u0442\u044f \u043d\u0438\u043a\u0442\u043e \u0435\u0435 \u0438 \u043d\u0435 \u0432\u0438\u0434\u0435\u043b.\n\u0412\u043e \u0432\u0441\u044f\u043a\u043e\u043c \u0441\u043b\u0443\u0447\u0430\u0435 \u0438\u0437 \u0436\u0438\u0432\u044b\u0445...\n \u041e\u0439, \u0447\u0442\u043e \u044d\u0442\u043e \u0442\u0430\u043c \u0448\u0435\u0432\u0435\u043b\u0438\u0442\u0441\u044f?";
this.data.h.cortana_say_105="\u0422\u0441\u0441-\u0441\u0441\u0441\u0441. \u0423\u0431\u0438\u0439\u0446\u044b! \n\u041d\u0435 \u043f\u0440\u043e\u0439\u0442\u0438 \u0432\u0430\u043c \u0437\u0434\u0435\u0441\u044c, \u0443\u0431\u0438\u0439\u0446\u044b, \u043c\u044b \u043d\u0435 \u043f\u0443\u0441\u0442\u0438\u043c! \u0422\u0441\u0441\u0441-\u0441\u0441-\u0441\u0441";this.data.h.cortana_say_106="\u0423\u0431\u0438\u0439\u0446\u044b? \u041e \u0447\u0435\u043c \u044d\u0442\u043e \u0442\u044b, \u043f\u0430\u0443\u0447\u0435\u043a?";
this.data.h.cortana_say_107="\u0412\u044b \u0443\u0431\u0438\u043b\u0438 \u043d\u0430\u0448 \u0432\u044b\u0432\u043e\u0434\u043e\u043a \u0432 \u0433\u043e\u0440\u043e\u0434\u0441\u043a\u043e\u043c \u0433\u043d\u0435\u0437\u0434\u0435! \n\u041a\u043e\u0440\u043e\u043b\u0435\u0432\u0430 \u0437\u043b\u0438\u0442\u0441\u044f! \u041d\u0435 \u043f\u0440\u043e\u0439\u0442\u0438 \u0443\u0431\u0438\u0439\u0446\u0430\u043c \u0442\u0443\u0442!";this.data.h.cortana_say_108=", \u043f\u043e\u0445\u043e\u0436\u0435 \u0431\u0435\u0437 \u0431\u043e\u044f \u043e\u043d\u0438 \u043d\u0430\u0441 \u043d\u0435 \u043f\u0440\u043e\u043f\u0443\u0441\u0442\u044f\u0442.";
this.data.h.cortana_say_123="\u0423\u0440\u0430, \u043f\u0430\u0443\u0447\u044c\u044f \u0442\u0440\u043e\u043f\u0430 \u043f\u043e\u0437\u0430\u0434\u0438!";this.data.h.cortana_say_124="\u0412\u043f\u0435\u0440\u0435\u0434\u0438 \u0432\u0438\u0434\u043d\u0435\u0435\u0442\u0441\u044f \u043a\u0430\u043a\u0430\u044f-\u0442\u043e \u0445\u0438\u0436\u0438\u043d\u0430, \u0434\u0430\u0432\u0430\u0439 \u043f\u043e\u0441\u043c\u043e\u0442\u0440\u0438\u043c, \u0447\u0442\u043e \u0442\u0430\u043c.";this.data.h.cortana_say_125=
"\u041a\u0430\u0436\u0435\u0442\u0441\u044f \u044f \u0437\u043d\u0430\u044e \u043a\u0442\u043e \u0437\u0434\u0435\u0441\u044c \u0436\u0438\u0432\u0435\u0442. \u041e\u0442\u0448\u0435\u043b\u044c\u043d\u0438\u043a. \n\u041e\u043d \u0438\u0441\u043a\u0443\u0441\u043d\u044b\u0439 \u0447\u0430\u0440\u043e\u0434\u0435\u0439, \u0434\u0430\u0432\u0430\u0439 \u0437\u0430\u0439\u0434\u0435\u043c \u043a \u043d\u0435\u043c\u0443 \u0432 \u0433\u043e\u0441\u0442\u0438.";this.data.h.cortana_say_126="\u041a\u0442\u043e \u0432\u044b \u0442\u0430\u043a\u0438\u0435? \u0427\u0442\u043e \u043d\u0443\u0436\u043d\u043e \u0432\u0430\u043c \u0442\u0443\u0442?";
this.data.h.cortana_say_127="\u041c\u044b \u043f\u0443\u0442\u043d\u0438\u043a\u0438 \u0438\u0437 \u0420\u0438\u0432\u0435\u0440\u0444\u043e\u0440\u0442\u0430. \u0418\u0434\u0435\u043c \u043a \u0440\u0430\u0437\u0432\u0430\u043b\u0438\u043d\u0430\u043c \u0441\u0442\u0430\u0440\u043e\u0433\u043e \u0444\u043e\u0440\u0442\u0430.";this.data.h.cortana_say_128="\u0410-\u0430-\u0430, \u043f\u043e\u043d\u044f\u0442\u043d\u043e. \u041f\u043b\u043e\u0445\u0430\u044f \u0437\u0430\u0442\u0435\u044f. \n\u041f\u0435\u0440\u0435\u0434 \u0444\u043e\u0440\u0442\u043e\u043c \u0440\u0430\u0437\u0431\u0438\u043b\u0438 \u043b\u0430\u0433\u0435\u0440\u044c \u0440\u0430\u0437\u0431\u043e\u0439\u043d\u0438\u043a\u0438 \u0438 \u0433\u0440\u0430\u0431\u044f\u0442 \u0432\u0441\u0435\u0445 \u043f\u0443\u0442\u043d\u0438\u043a\u043e\u0432.";
this.data.h.cortana_say_129="\u0421\u043f\u0430\u0441\u0438\u0431\u043e, \u043c\u044b \u0441\u043b\u044b\u0448\u0430\u043b\u0438 \u043f\u0440\u043e \u0440\u0430\u0437\u0431\u043e\u0439\u043d\u0438\u043a\u043e\u0432. \n\u0421\u043a\u0430\u0436\u0438 \u043d\u0430\u043c, \u0434\u0440\u0443\u0433, \u0447\u0442\u043e \u0437\u0430\u0431\u044b\u043b \u0442\u044b \u0432 \u044d\u0442\u043e\u0439 \u0433\u043b\u0443\u0448\u0438?";this.data.h.cortana_say_130="\u042f \u0442\u0443\u0442 \u0440\u0430\u0431\u043e\u0442\u0430\u044e! \u0422\u0443\u0442 \u043a \u044e\u0433\u0443 \u043f\u043e\u043b\u043d\u043e \u043f\u0430\u0443\u043a\u043e\u0432. \u0418\u0437 \u0438\u0445 \u044f\u0434\u0430 \n\u043f\u043e\u043b\u0443\u0447\u0430\u0435\u0442\u0441\u044f \u043e\u0442\u043b\u0438\u0447\u043d\u043e\u0435 \u0442\u043e\u043d\u0438\u0437\u0438\u0440\u0443\u044e\u0449\u0435\u0435 \u0437\u0435\u043b\u044c\u0435! \u042d\u0442\u0438\u043c \u0438 \u0436\u0438\u0432\u0443. \n\u0415\u0441\u043b\u0438 \u0441\u043c\u043e\u0436\u0435\u0442\u0435 \u0434\u043e\u0431\u044b\u0442\u044c \u043d\u0435\u043c\u043d\u043e\u0433\u043e \u043f\u0430\u0443\u0447\u044c\u0435\u0433\u043e \u044f\u0434\u0430 \u2014 \u043d\u0435\u0441\u0438\u0442\u0435 \u043c\u043d\u0435.";
this.data.h.cortana_say_131="\u0422\u0430\u043a \u0438 \u0441\u0434\u0435\u043b\u0430\u0435\u043c! \n\u0418\u0434\u0435\u043c, ";this.data.h.cortana_say_132="\u0412\u043e\u0442 \u043e\u043d, \u0431\u0430\u043d\u0434\u0438\u0442\u0441\u043a\u0438\u0439 \u043b\u0430\u0433\u0435\u0440\u044c. \u0421\u043c\u043e\u0442\u0440\u0438 \u043a\u0430\u043a\u0438\u0435 \u0440\u043e\u0436\u0438... \n\u0417\u043b\u043e\u0434\u0435\u0438, \u0441\u0440\u0430\u0437\u0443 \u0432\u0438\u0434\u043d\u043e.";this.data.h.cortana_say_133=
"\u0412\u043e-\u043e-\u043e\u043d, \u043a \u0432\u043e\u0441\u0442\u043e\u043a\u0443 \u043e\u0442\u0441\u044e\u0434\u0430 \u0443\u0436\u0435 \u0432\u0438\u0434\u0435\u043d \u0444\u043e\u0440\u0442, \n\u043d\u043e, \u0447\u0442\u043e\u0431\u044b \u043f\u0440\u043e\u0439\u0442\u0438 \u043a \u043d\u0435\u043c\u0443 \u2013 \u043d\u0430\u0434\u043e \u0440\u0430\u0437\u043e\u0431\u0440\u0430\u0442\u044c\u0441\u044f \u0441 \u0431\u0430\u043d\u0434\u043e\u0439.";this.data.h.cortana_say_134="\u0412\u043e\u0442 \u043c\u044b \u0438 \u0434\u043e\u0431\u0440\u0430\u043b\u0438\u0441\u044c \u0434\u043e \u0444\u043e\u0440\u0442\u0430. \n\u0421\u043a\u0432\u0435\u0440\u043d\u043e\u0435 \u043c\u0435\u0441\u0442\u043e... \n\u0414\u0430\u0432\u0430\u0439 \u043e\u0441\u043c\u043e\u0442\u0440\u0438\u043c\u0441\u044f.";
this.data.h.cortana_say_135="\u0427\u0435\u0440\u0442, \u043f\u043e\u0445\u043e\u0436\u0435 \u0433\u0434\u0435-\u0442\u043e \u043f\u043e\u0431\u043b\u0438\u0437\u043e\u0441\u0442\u0438 \u0433\u043e\u0431\u043b\u0438\u043d\u044b, \u0447\u0443\u044e \u0438\u0445 \u0432\u043e\u043d\u044c.";this.data.h.cortana_say_136="\u041c\u044f\u0441\u043a\u043e \u043f\u0440\u0438-\u0438-\u0438-\u0431\u044b\u043b\u043e! \u041d\u044f\u043c! \n\u041c\u044f\u0441\u043a\u043e \u043f\u0440\u0438\u0431\u044b\u043b\u043e!";
this.data.h.cortana_say_137="\u0421\u043c\u043e\u0442\u0440\u0438 \u043a\u0430\u043a\u043e\u0439 \u043f\u0440\u044b\u0442\u043a\u0438\u0439! \n\u041f\u043e\u0445\u043e\u0436\u0435, \u0447\u0442\u043e \u043d\u0430\u043c \u043f\u043e\u0432\u0435\u0437\u043b\u043e. \n\u0416\u0438\u0432\u043e\u0439 \u0433\u043e\u0431\u043b\u0438\u043d \u043d\u0430\u043c \u0441\u043a\u0430\u0436\u0435\u0442 \u0433\u043e\u0440\u0430\u0437\u0434\u043e \u0431\u043e\u043b\u044c\u0448\u0435, \u0447\u0435\u043c \u043f\u0440\u043e\u0441\u0442\u043e\u0439 \u043e\u0441\u043c\u043e\u0442\u0440 \u0440\u0443\u0438\u043d.";
this.data.h.cortana_say_138="\u041d\u0430\u0448\u0430 \u0441\u0442\u0430\u043b\u044c \u0431\u044b\u0441\u0442\u0440\u043e \u0435\u0433\u043e \u0440\u0430\u0437\u0433\u043e\u0432\u043e\u0440\u0438\u0442!";this.data.h.cortana_say_139="\u041d\u0443, \u0437\u0435\u043b\u0435\u043d\u044b\u0439, \u0433\u0434\u0435 \u0442\u0432\u043e\u0439 \u0445\u043e\u0437\u044f\u0438\u043d?";this.data.h.cortana_say_140="\u0425\u0430-\u0445\u0430-\u0445\u0430-\u0445\u0430-\u0445\u0430. \u042f \u0441\u043c\u0435-\u0435\u0442\u0441\u044f \u043d\u0430\u0434 \u0432\u0430\u043c\u0438! \n\u0421\u0435\u0433\u043e\u0434\u043d\u044f \u044f \u0431\u0443\u0434\u0435\u0442 \u043a\u0443\u0448\u0430\u0442\u044c \u0432\u043a\u0443\u0441\u043d\u043e-\u0432\u043a\u0443\u0441\u043d\u043e!";
this.data.h.cortana_say_141="\u0425\u0435\u0439! \u0421\u043a\u043e\u0440\u043e \u0432\u0430\u043c \u0432\u0441\u0435\u043c \u043a\u043e\u043d\u0435\u0446! \u0425\u0430\u0445\u0430! \n\u0421\u043a\u043e\u0440\u043e \u0432\u0441\u0435\u043c \u043a\u043e\u043d\u0435-\u0435-\u0435-\u0435-\u0446!";this.data.h.cortana_say_142="\u041d\u0443, \u0433\u0430\u0434, \u0434\u0435\u0440\u0436\u0438\u0441\u044c! \n\u041e\u0422\u0420\u042f\u0414! \u041a \u0411\u041e\u042e!";this.data.h.cortana_say_143="\u0427\u0442\u043e?! \u041d\u0415\u0415\u0415\u0422!!! \u042d\u0442\u043e \u043d\u0435\u0432\u043e\u0437\u043c\u043e\u0436\u043d\u043e! \n\u0425\u041e\u0417\u042f\u0418\u041d \u0431\u0443\u0434\u0435\u0442 \u0437\u043b\u0438\u0442\u044c\u0441\u044f!";
this.data.h.cortana_say_144="*\u0425\u0432\u0430\u0442\u0430\u0435\u0442 \u0413\u043e\u0431\u043b\u0438\u043d\u0430 \u0437\u0430 \u0433\u043e\u0440\u043b\u043e*\n \u0412\u043e\u0442 \u0445\u043e\u0437\u044f\u0439\u0438\u043d \u0442\u0432\u043e\u0439 \u043d\u0430\u043c \u0438 \u043d\u0443\u0436\u0435\u043d! \n\u0420\u0430\u0441\u0441\u043a\u0430\u0437\u044b\u0432\u0430\u0439, \u0433\u0434\u0435 \u043e\u043d?";this.data.h.cortana_say_145="\u041e-\u043e-\u043e-\u043e\u043d \u043e\u0447\u0435\u043d\u044c \u0434\u0430\u043b\u0435\u043a\u043e \u043d\u0430 \u0441\u0435\u0432\u0435\u0440\u043e-\u0432\u043e\u0441\u0442\u043e\u043a\u0435. \u041d\u0435 \u043d\u0430\u0439\u0442\u0438 \u0432\u0430\u043c \u0415\u0413\u041e!";
this.data.h.cortana_say_146="\u0417\u0430\u0442\u043e \u0441\u043a\u043e\u0440\u043e \u041e\u041d \u043d\u0430\u0439\u0434\u0435\u0442 \u0432\u0441\u0435-\u0435-\u0435-\u0445 \u0432\u0430\u0441!.";this.data.h.cortana_say_147="\u0421\u043a\u043e\u0440\u043e-\u0441\u043a\u043e\u0440\u043e, \u0445\u0435-\u0445\u0435, \u0441\u043a\u043e\u0440\u043e \n\u0432\u0441\u0435 \u0436\u0438\u0432\u044b\u0435 \u0441\u0442\u0430\u043d\u0443\u0442 \u0441\u043b\u0443\u0433\u0430\u043c\u0438 \u0425\u041e\u0417\u042f\u0418\u041d\u0410!";
this.data.h.cortana_say_148="\u041d\u043e \u0432\u0430\u043c \u0415\u0433\u043e \u043d\u0435 \u043e\u0434\u043e\u043b\u0435\u0442\u044c \u0431\u0435\u0437 \u0441\u0438\u043b\u044c\u043d\u044b\u0445 \u0430\u0440\u0442\u0435\u0444\u0430\u043a\u0442\u043e\u0432! \n\u0414\u0430\u0436\u0435 \u0432\u0441\u0435\u043c \u0432\u0430\u0448\u0438\u043c \u043e\u0442\u0440\u044f\u0434\u043e\u043c, \u0445\u0430-\u0445\u0430-\u0445\u0430-\u0445\u0430!";this.data.h.cortana_say_149="\u0410\u0440\u0442\u0435\u0444\u0430\u043a\u0442\u044b?";
this.data.h.cortana_say_150="\u041e\u0439, \u0425\u041e\u0417\u042f\u0418\u041d \u0431\u0443\u0434\u0435\u0442\u044c \u0441\u0438\u043b\u044c\u043d\u043e \u0441\u0438\u043b\u044c\u043d\u043e \u0437\u043b\u0438\u0442\u044c\u0441\u044f... \n\u0410\u0440\u0442\u0435\u0444\u0430\u043a\u0442\u044b? \u041d\u0435 \u0437\u043d\u0430\u044e \u043d\u0438\u043a\u0430\u043a\u0438\u0435 \u0430\u0440\u0442\u0435\u0444\u0430\u043a\u0442\u044b!";this.data.h.cortana_say_151="\u0421 \u044d\u0442\u0438\u043c \u0437\u0435\u043b\u0435\u043d\u044b\u043c \u0432\u0441\u0435 \u043f\u043e\u043d\u044f\u0442\u043d\u043e. \n\u0427\u0442\u043e \u0436, \u043a\u0430\u0436\u0435\u0442\u0441\u044f, \u0443 \u043d\u0430\u0441 \u043d\u043e\u0432\u043e\u0435 \u0437\u0430\u0434\u0430\u043d\u0438\u0435 - \u0441\u043f\u0430\u0441\u0442\u0438 \u0432\u0435\u0441\u044c \u043c\u0438\u0440!";
this.data.h.cortana_say_152="\u041f\u0443\u0442\u044c \u043d\u0430 \u0432\u043e\u0441\u0442\u043e\u043a \u043b\u0435\u0436\u0438\u0442 \u0447\u0435\u0440\u0435\u0437 \u00ab\u041f\u0435\u0440\u0435\u0432\u0430\u043b \u043c\u0435\u0440\u0442\u0432\u0435\u0446\u043e\u0432\u00bb. \n\u0414\u0430\u0432\u043d\u0435\u043d\u044c\u043a\u043e \u044f \u0442\u0430\u043c \u043d\u0435 \u0431\u044b\u0432\u0430\u043b\u0430. \n\u041d\u043e \u0434\u043e\u0440\u043e\u0433\u0443 \u043f\u043e\u043c\u043d\u044e, \u043e\u0447\u0435\u043d\u044c \u0445\u043e\u0440\u043e\u0448\u043e \u043f\u043e\u043c\u043d\u044e...";
this.data.h.cortana_say_153="\u041f\u043e \u043f\u0443\u0442\u0438 \u0440\u0430\u0437\u0443\u0437\u043d\u0430\u0435\u043c \u043f\u0440\u043e \u043a\u0430\u043a\u0438\u0435 \u0438\u043c\u0435\u043d\u043d\u043e \u0430\u0440\u0442\u0435\u0444\u0430\u043a\u0442\u044b \n\u043f\u0440\u043e\u0433\u043e\u0432\u043e\u0440\u0438\u043b\u0441\u044f \u0413\u043e\u0431\u043b\u0438\u043d.";this.data.h.cortana_say_154="\u00ab\u041f\u0435\u0440\u0435\u0432\u0430\u043b \u043c\u0435\u0440\u0442\u0432\u0435\u0446\u043e\u0432\u00bb \u2014 \u043e\u0434\u043e\u043b\u0435\u0442\u044c \u0435\u0433\u043e \u043d\u0435\u043f\u0440\u043e\u0441\u0442\u043e. \n\u041f\u0435\u0440\u0435\u0432\u0430\u043b \u043e\u0445\u0440\u0430\u043d\u044f\u0435\u0442\u0441\u044f \u0433\u043e\u0440\u043d\u044b\u043c\u0438 \u0442\u0440\u043e\u043b\u043b\u044f\u043c\u0438.";
this.data.h.cortana_say_155="\u042d\u0442\u043e \u043e\u0447\u0435\u043d\u044c \u0442\u0443\u043f\u044b\u0435, \u043d\u043e \u0432 \u0442\u043e\u0436\u0435 \u0432\u0440\u0435\u043c\u044f \u0441\u0438\u043b\u044c\u043d\u044b\u0435 \u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0430!";this.data.h.cortana_say_156="\u0415\u0441\u043b\u0438 \u0443\u0434\u0430\u0441\u0442\u0441\u044f \u0441 \u043d\u0438\u043c\u0438 \u0440\u0430\u0437\u043e\u0431\u0440\u0430\u0442\u044c\u0441\u044f, \n\u0442\u043e \u043f\u0435\u0440\u0435\u0432\u0430\u043b \u043f\u0440\u043e\u0439\u0434\u0435\u043c \u0431\u0435\u0437 \u043f\u0440\u043e\u0431\u043b\u0435\u043c.";
this.data.h.cortana_say_157="\u041e\u0442\u043b\u0438\u0447\u043d\u043e, \u043f\u0435\u0440\u0435\u0432\u0430\u043b \u043f\u0440\u0435\u043e\u0434\u043e\u043b\u0435\u043d.";this.data.h.cortana_say_158="\u0421\u0440\u0430\u0437\u0443 \u0437\u0430 \u043f\u0435\u0440\u0435\u0432\u0430\u043b\u043e\u043c \u043d\u0430\u0445\u043e\u0434\u0438\u0442\u0441\u044f \u0434\u0435\u0440\u0435\u0432\u043d\u044f. \n\u041e\u0441\u0442\u0430\u043d\u043e\u0432\u0438\u043c\u0441\u044f \u043d\u0430 \u043f\u043e\u0441\u0442\u043e\u044f\u043b\u043e\u043c \u0434\u0432\u043e\u0440\u0435.";
this.data.h.cortana_say_159="\u0417\u0430\u0442\u0435\u043c \u0434\u0432\u0438\u043d\u0435\u043c\u0441\u044f \u0432 \u0420\u0430\u0441\u0442\u0445\u0435\u043b\u044c\u043c, \u0442\u0430\u043c \u0436\u0438\u0432\u0435\u0442 \u043c\u043e\u044f \u0437\u043d\u0430\u043a\u043e\u043c\u0430\u044f \u0412\u043e\u043b\u0448\u0435\u0431\u043d\u0438\u0446\u0430. \n\u0420\u0430\u0441\u043f\u0440\u043e\u0441\u0438\u043c \u0435\u0435 \u043e\u0431 \u0430\u0440\u0442\u0435\u0444\u0430\u043a\u0442\u0430\u0445, \u043f\u0440\u043e \u043a\u043e\u0442\u043e\u0440\u044b\u0435 \u043f\u0440\u043e\u0433\u043e\u0432\u043e\u0440\u0438\u043b\u0441\u044f \u0433\u043e\u0431\u043b\u0438\u043d.";
this.data.h.cortana_say_160="*\u0438\u0434\u0435\u043c \u0432 \u0434\u0435\u0440\u0435\u0432\u043d\u044e*";this.data.h.cortana_say_161="\u0421\u0442\u0440\u0430\u043d\u043d\u043e, \u0432 \u0434\u0435\u0440\u0435\u0432\u043d\u0435 \u0441\u043e\u0432\u0441\u0435\u043c \u043f\u0443\u0441\u0442\u043e. \u0427\u0442\u043e \u0437\u0434\u0435\u0441\u044c \u043f\u0440\u043e\u0438\u0437\u043e\u0448\u043b\u043e? \n\u041d\u0430 \u0443\u043b\u0438\u0446\u0435 \u043d\u0438 \u0434\u0443\u0448\u0438...";this.data.h.cortana_say_162=
"\u0421\u043c\u0435\u0440\u0442\u043d\u044b\u0435, \u0442\u0435\u043f\u0435\u0440\u044c \u044d\u0442\u043e \u043d\u0430\u0448\u0430 \u0437\u0435\u043c\u043b\u044f... \n\u0418 \u0441\u043a\u043e\u0440\u043e \u0432\u044b \u043f\u0440\u0438\u0441\u043e\u0435\u0434\u0438\u043d\u0438\u0442\u0435\u0441\u044c \u043a \u043d\u0430\u043c...";this.data.h.cortana_say_163="\u041f\u043b\u043e\u0445\u043e \u0434\u0435\u043b\u043e, \u0441\u043a\u0435\u043b\u0435\u0442\u043e\u0432 \u043e\u0447\u0435\u043d\u044c \u0442\u0440\u0443\u0434\u043d\u043e \u043e\u0434\u043e\u043b\u0435\u0442\u044c. \n\u041d\u043e \u0434\u0440\u0443\u0433\u043e\u0439 \u0434\u043e\u0440\u043e\u0433\u0438 \u0432 \u0433\u043e\u0440\u043e\u0434 \u043d\u0435\u0442.";
this.data.h.cortana_say_164="\u0412\u043e\u0442 \u043c\u044b \u0438 \u0432 \u0420\u0430\u0441\u0442\u0445\u0435\u043b\u044c\u043c\u0435. \u042f \u0437\u043d\u0430\u044e \u0442\u0443\u0442 \u043e\u0434\u043d\u0443 \u0412\u043e\u043b\u0448\u0435\u0431\u043d\u0438\u0446\u0443. \n\u0412\u043e\u0437\u043c\u043e\u0436\u043d\u043e, \u043e\u043d\u0430 \u0440\u0430\u0441\u0441\u043a\u0430\u0436\u0435\u0442 \u043d\u0430\u043c \u0447\u0442\u043e-\u0442\u043e \u043e\u0431 \u0430\u0440\u0442\u0435\u0444\u0430\u043a\u0442\u0430\u0445 \u043f\u0440\u043e\u0442\u0438\u0432 \u041b\u0438\u0447\u0430.";
this.data.h.cortana_say_165="\u0417\u0430\u0439\u0434\u0435\u043c \u043a \u043d\u0435\u0439 \u0432 \u043b\u0430\u0432\u043a\u0443.";this.data.h.cortana_say_166="\u0421\u044e\u0434\u0430.";this.data.h.cortana_say_167="\u041a\u043e\u0433\u043e \u044f \u0432\u0438\u0436\u0443! \u0420\u0430\u0434\u0430 \u0442\u0435\u0431\u044f \u0432\u0438\u0434\u0435\u0442\u044c, \u041c\u044d\u0433. \n\u0427\u0442\u043e \u043f\u0440\u0438\u0432\u0435\u043b\u043e \u0442\u0435\u0431\u044f \u0432 \u0420\u0430\u0441\u0442\u0445\u0435\u043b\u044c\u043c? \u041d\u0435\u043b\u0435\u0433\u043a\u0438\u0439 \u043f\u0443\u0442\u044c \u0442\u044b \u043f\u0440\u043e\u0434\u0435\u043b\u0430\u043b\u0430.";
this.data.h.cortana_say_168="\u0422\u044b \u043f\u0440\u0430\u0432\u0430. \u041c\u044b \u0438\u0434\u0435\u043c \u043d\u0430 \u0432\u043e\u0441\u0442\u043e\u043a, \u043d\u0430\u0448\u0430 \u0446\u0435\u043b\u044c - \u042d\u043b\u044c\u043e\u0434\u0434\u0443\u0440.";this.data.h.cortana_say_169="\u041c\u044b \u0443\u0437\u043d\u0430\u043b\u0438, \u0447\u0442\u043e \u0435\u0441\u0442\u044c \u043d\u0435\u043a\u0438\u0435 \u0430\u0440\u0442\u0435\u0444\u0430\u043a\u0442\u044b, \u043a\u043e\u0442\u043e\u0440\u044b\u0435 \u043f\u043e\u043c\u043e\u0433\u0443\u0442 \u043e\u0434\u043e\u043b\u0435\u0442\u044c \u0435\u0433\u043e. \n\u0421\u043b\u044b\u0448\u0430\u043b\u0430 \u043f\u0440\u043e \u0442\u0430\u043a\u0438\u0435?";
this.data.h.cortana_say_170="\u0425\u043c... \n\u041f\u043e\u0445\u043e\u0436\u0435, \u0447\u0442\u043e \u0440\u0435\u0447\u044c \u0438\u0434\u0435\u0442 \u043e \u043b\u0435\u0433\u0435\u043d\u0434\u0430\u0440\u043d\u044b\u0445 \u0430\u0440\u0442\u0435\u0444\u0430\u043a\u0442\u0430\u0445 \u0421\u0438\u043b\u044b.";this.data.h.cortana_say_171="\u041a\u0430\u043a \u0433\u043b\u0430\u0441\u044f\u0442 \u043b\u0435\u0433\u0435\u043d\u0434\u044b \u2013 \u043e\u0431\u043b\u0430\u0434\u0430\u0442\u0435\u043b\u0438 \u0442\u0430\u043a\u043e\u0439 \u044d\u043a\u0438\u043f\u0438\u0440\u043e\u0432\u043a\u0438 \u043c\u043e\u0433\u0443\u0442 \n \u043f\u043e\u0431\u0435\u0434\u0438\u0442\u044c \u0441\u0430\u043c\u044b\u0445 \u0441\u0442\u0440\u0430\u0448\u043d\u044b\u0445 \u0447\u0443\u0434\u0438\u0449 \u043d\u0430 \u0441\u0432\u0435\u0442\u0435.";
this.data.h.cortana_say_172="\u041d\u043e \u0437\u0430\u043f\u043e\u043b\u0443\u0447\u0438\u0442\u044c \u0438\u0445 \u043e\u0447\u0435\u043d\u044c \u0442\u0440\u0443\u0434\u043d\u043e. \n\u041f\u0440\u0430\u043a\u0442\u0438\u0447\u0435\u0441\u043a\u0438 \u043d\u0435\u0432\u043e\u0437\u043c\u043e\u0436\u043d\u043e.";this.data.h.cortana_say_173="\u041f\u043e\u0434\u0441\u043a\u0430\u0436\u0438 \u0445\u043e\u0442\u044f \u0431\u044b \u0441 \u0447\u0435\u0433\u043e \u043d\u0430\u0447\u0430\u0442\u044c \u043f\u043e\u0438\u0441\u043a\u0438?";
this.data.h.cortana_say_174="\u042f \u0437\u043d\u0430\u044e \u0442\u043e\u043b\u044c\u043a\u043e \u043f\u0440\u043e \u043e\u0434\u0438\u043d \u0442\u0430\u043a\u043e\u0439 \u043f\u0440\u0435\u0434\u043c\u0435\u0442 \u2013 \u00ab\u041d\u0430\u0440\u0443\u0447\u0438 \u0410\u0440\u0430\u0433\u043e\u043d\u0430\u00bb. \n\u0418 \u043d\u0430\u0439\u0442\u0438 \u0438\u0445 \u043c\u043e\u0436\u043d\u043e \u0437\u0434\u0435\u0441\u044c, \u0432 \u0420\u0430\u0441\u0442\u0445\u0435\u043b\u044c\u043c\u0435. \n\u041e\u043d\u0438 \u043d\u0430\u0445\u043e\u0434\u044f\u0442\u0441\u044f \u0432 \u043a\u043e\u043b\u043b\u0435\u043a\u0446\u0438\u0438 \u043d\u0430\u0448\u0435\u0433\u043e \u043b\u043e\u0440\u0434\u0430 \u00ab\u041c\u0430\u0440\u043a\u0443\u0441\u0430\u00bb.";
this.data.h.cortana_say_175="\u0412\u043e\u0437\u043c\u043e\u0436\u043d\u043e, \u0435\u0441\u043b\u0438 \u0432\u0430\u043c \u0443\u0434\u0430\u0441\u0442\u0441\u044f \u0438\u0445 \u0437\u0430\u043f\u043e\u043b\u0443\u0447\u0438\u0442\u044c \u2014 \n\u0432\u044b \u0441\u043c\u043e\u0433\u043b\u0438 \u0431\u044b \u043f\u043e\u043d\u044f\u0442\u044c \u0433\u0434\u0435 \u0438\u0441\u043a\u0430\u0442\u044c \u0434\u0440\u0443\u0433\u0438\u0435 \u0430\u0440\u0442\u0435\u0444\u0430\u043a\u0442\u044b.";this.data.h.cortana_say_176=
"\u041d\u043e \u0441\u043e\u043c\u043d\u0435\u0432\u0430\u044e\u0441\u044c, \u0447\u0442\u043e \u041b\u043e\u0440\u0434 \u041c\u0430\u0440\u043a\u0443\u0441 \u0442\u0430\u043a \u043f\u0440\u043e\u0441\u0442\u043e \u0440\u0430\u0441\u0441\u0442\u0430\u043d\u0435\u0442\u0441\u044f \u0441 \u044d\u043b\u0435\u043c\u0435\u043d\u0442\u043e\u043c \u0441\u0432\u043e\u0435\u0439 \u043a\u043e\u043b\u043b\u0435\u043a\u0446\u0438\u0438. \n\u0421\u043a\u043e\u0440\u0435\u0435 \u0432\u0441\u0435\u0433\u043e, \u043e\u043d \u0434\u0430\u0436\u0435 \u0433\u043e\u0432\u043e\u0440\u0438\u0442\u044c \u0441 \u0412\u0430\u043c\u0438 \u043d\u0435 \u0441\u0442\u0430\u043d\u0435\u0442. \n\u0414\u043b\u044f \u043d\u0430\u0447\u0430\u043b\u0430, \u043f\u043e\u043f\u0440\u043e\u0431\u0443\u0439\u0442\u0435 \u0437\u0430\u0441\u043b\u0443\u0436\u0438\u0442\u044c \u0435\u0433\u043e \u0434\u043e\u0432\u0435\u0440\u0438\u0435.";
this.data.h.cortana_say_177="\u041a \u0441\u0447\u0430\u0441\u0442\u044c\u044e, \u0443 \u0412\u0430\u0441 \u0435\u0441\u0442\u044c \u0442\u0430\u043a\u0430\u044f \u0432\u043e\u0437\u043c\u043e\u0436\u043d\u043e\u0441\u0442\u044c. \n\u0412 \u043f\u0440\u0438\u0433\u043e\u0440\u043e\u0434\u0435 \u043e\u0440\u0443\u0434\u0443\u0435\u0442 \u0431\u0430\u043d\u0434\u0430 \u0433\u043e\u043b\u043e\u0432\u043e\u0440\u0435\u0437\u043e\u0432. \u0415\u0441\u043b\u0438 \u0412\u044b \u0443\u0431\u044c\u0435\u0442\u0435 \n\u043d\u0435\u0441\u043a\u043e\u043b\u044c\u043a\u0438\u0445 \u0438\u0437 \u043d\u0438\u0445 \u2014 \u041b\u043e\u0440\u0434 \u043f\u043e\u0433\u043e\u0432\u043e\u0440\u0438\u0442 \u0441 \u0432\u0430\u043c\u0438.";
this.data.h.cortana_say_178="\u041c\u044b \u0432\u0441\u0435 \u043f\u043e\u043d\u044f\u043b\u0438, \u0441\u043f\u0430\u0441\u0438\u0431\u043e \u0442\u0435\u0431\u0435, \u0412\u0430\u043d\u0435\u0441\u0441\u0430. \n\u0423\u0432\u0438\u0434\u0438\u043c\u0441\u044f!";this.data.h.cortana_say_179="\u0412\u043e\u0442 \u0438 \u043a\u0440\u0435\u043f\u043e\u0441\u0442\u044c \u0420\u0430\u0441\u0442\u0445\u0435\u043b\u044c\u043c\u0430. \n\u0418\u0434\u0435\u043c \u043a \u041b\u043e\u0440\u0434\u0443.";this.data.h.cortana_say_180=
"\u041c\u043d\u0435 \u0443\u0436\u0435 \u0434\u043e\u043b\u043e\u0436\u0438\u043b\u0438 \u043e \u0432\u0430\u0448\u0435\u0439 \u0443\u0441\u043b\u0443\u0433\u0435 \u0441 \u0431\u0430\u043d\u0434\u0438\u0442\u0430\u043c\u0438. \n\u041a\u0430\u043a\u0443\u044e \u043d\u0430\u0433\u0440\u0430\u0434\u0443 \u0445\u043e\u0442\u0438\u0442\u0435, \u0434\u0440\u0443\u0437\u044c\u044f \u043c\u043e\u0438?";this.data.h.cortana_say_181="*\u0420\u0430\u0441\u0441\u043a\u0430\u0437\u044b\u0432\u0430\u0435\u0442 \u041b\u043e\u0440\u0434\u0443 \u043d\u0430\u0448\u0443 \u0438\u0441\u0442\u043e\u0440\u0438\u044e*";
this.data.h.cortana_say_182="\u0417\u043d\u0430\u0447\u0438\u0442, \u0412\u0430\u043c \u043d\u0443\u0436\u043d\u044b \u041d\u0430\u0440\u0443\u0447\u0438 \u0410\u0440\u0430\u0433\u043e\u043d\u0430!?\n \u041d\u0435 \u0441\u043a\u0440\u043e\u044e, \u044d\u0442\u043e \u043e\u0447\u0435\u043d\u044c \u0446\u0435\u043d\u043d\u0430\u044f \u0432\u0435\u0449\u044c \u0434\u043b\u044f \u043c\u0435\u043d\u044f.";this.data.h.cortana_say_183="\u041d\u043e \u044f \u043d\u0430\u0441\u043b\u044b\u0448\u0430\u043d \u043e \u0441\u043b\u0430\u0432\u0435 \u0412\u0430\u0448\u0435\u0433\u043e \u043e\u0442\u0440\u044f\u0434\u0430. \n\u0414\u0443\u043c\u0430\u044e, \u0412\u044b \u0441\u043c\u043e\u0436\u0435\u0442\u0435 \u043e\u043a\u0430\u0437\u0430\u0442\u044c \u043c\u043d\u0435 \u043d\u0435\u0431\u043e\u043b\u044c\u0448\u0443\u044e \u0443\u0441\u043b\u0443\u0433\u0443, \n\u0430 \u0432\u0437\u0430\u043c\u0435\u043d \u044f \u043e\u0442\u0434\u0430\u043c \u0412\u0430\u043c \u043d\u0430\u0440\u0443\u0447\u0438.";
this.data.h.cortana_say_184="\u0427\u0442\u043e \u043d\u0443\u0436\u043d\u043e \u0441\u0434\u0435\u043b\u0430\u0442\u044c?";this.data.h.cortana_say_185="\u0423 \u043c\u0435\u043d\u044f \u0432 \u043a\u0440\u0435\u043f\u043e\u0441\u0442\u0438 \u043f\u043e\u044f\u0432\u0438\u043b\u043e\u0441\u044c \u0433\u043d\u0435\u0437\u0434\u043e \u043e\u0431\u043e\u0440\u043e\u0442\u043d\u0435\u0439. \n\u041a\u0430\u0436\u0434\u044b\u0439 \u0434\u0435\u043d\u044c \u043e\u043d\u0438 \u0443\u0431\u0438\u0432\u0430\u044e\u0442 \u043c\u043e\u0438\u0445 \u043b\u044e\u0434\u0435\u0439, \u043c\u044b \u043d\u0438\u0447\u0435\u0433\u043e \u043d\u0435 \u043c\u043e\u0436\u0435\u043c \u0441 \u043d\u0438\u043c\u0438 \u043f\u043e\u0434\u0435\u043b\u0430\u0442\u044c!";
this.data.h.cortana_say_186="\u0415\u0441\u043b\u0438 \u0432\u044b \u0441\u043c\u043e\u0436\u0435\u0442\u0435 \u0440\u0430\u0437\u043e\u0431\u0440\u0430\u0442\u044c\u0441\u044f \u0441 \u044d\u0442\u043e\u0439 \u043f\u0440\u043e\u0431\u043b\u0435\u043c\u043e\u0439 \u2014 \n \u044f \u043e\u0442\u0434\u0430\u043c \u0432\u0430\u043c \u0442\u043e, \u0447\u0442\u043e \u0412\u044b \u0438\u0449\u0435\u0442\u0435.";this.data.h.cortana_say_187="\u041c\u044b \u0433\u043e\u0442\u043e\u0432\u044b \u043f\u043e\u043c\u043e\u0447\u044c \u0412\u0430\u043c, \u041b\u043e\u0440\u0434 \u041c\u0430\u0440\u043a\u0443\u0441. \n";
